const panels={wallet:{title:'Wallet journey checklist',label:'WALLET UX',items:['Confirm the expected network before requesting an action.','Provide a visible disconnect route and handle account changes.','Explain wrong-network and rejected-request states in plain language.']},payment:{title:'Payment integrity checklist',label:'PAYMENT UX',items:['Display asset, amount, recipient, and expected fees before approval.','Separate submitted, pending, finalized, and failed states.','Give users a direct way to verify the transaction from a trusted explorer.']},observability:{title:'Observability checklist',label:'QA + RELIABILITY',items:['Capture actionable error context without exposing personal data.','Show the endpoint and failure category when RPC calls fail.','Write repro steps that another tester can repeat independently.']}};
const readiness=[['Define trusted sources','Document official RPC, explorer, and wallet destinations before enabling links.'],['Test wallet recovery','Validate disconnect, account-change, wrong-network, and rejected-transaction paths.'],['Review payment disclosure','Confirm asset, amount, recipient and fee information are visible before approval.'],['Create a repro bundle','Prepare concise steps, expected behavior, actual behavior, and public evidence.'],['Publish safety language','Make clear that users should never share recovery phrases or private keys.']];
const panelOutput=document.querySelector('#panel-output'),list=document.querySelector('#readiness-list'),count=document.querySelector('#progress-count'),toast=document.querySelector('#toast');
function renderPanel(key){const p=panels[key];panelOutput.innerHTML=`<div class="panel-title"><h3>${p.title}</h3><span>${p.label}</span></div><div class="panel-items">${p.items.map((item,i)=>`<div><span>0${i+1}</span>${item}</div>`).join('')}</div>`;document.querySelectorAll('.work-card').forEach(card=>card.classList.toggle('active',card.dataset.panel===key))}
function localArray(key){try{const value=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(value)?value:[]}catch{return[]}}
function readinessData(){return localArray('arc-desk-readiness').filter(id=>Number.isInteger(id)&&id>=0&&id<readiness.length)}
function renderReadiness(){const saved=readinessData();list.innerHTML=readiness.map(([title,text],i)=>`<article class="ready-item ${saved.includes(i)?'done':''}"><button class="ready-toggle" data-id="${i}" aria-label="Mark ${title} complete">✓</button><div><h3>${title}</h3><p>${text}</p></div><span class="status">${saved.includes(i)?'COMPLETE':'TO REVIEW'}</span></article>`).join('');count.textContent=`${saved.length} / ${readiness.length}`;document.querySelectorAll('.ready-toggle').forEach(b=>b.onclick=()=>toggleReady(+b.dataset.id))}
function toggleReady(id){let saved=readinessData();saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];localStorage.setItem('arc-desk-readiness',JSON.stringify(saved));renderReadiness();refreshBundleStats?.()}
function notify(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelectorAll('.work-card').forEach(card=>card.addEventListener('click',()=>renderPanel(card.dataset.panel)));
document.querySelector('#brief-form').addEventListener('submit',event=>{event.preventDefault();const title=document.querySelector('#issue-title').value.trim()||'Untitled issue';const surface=document.querySelector('#test-surface').value.trim()||'Not specified';const steps=document.querySelector('#repro-steps').value.trim()||'Not supplied';const expected=document.querySelector('#expected-result').value.trim()||'Not supplied';const actual=document.querySelector('#actual-result').value.trim()||'Not supplied';const evidence=document.querySelector('#evidence-url').value.trim();const text=`## ${title}\n\n### Environment\n- Test surface: ${surface}\n- Report generated: ${new Date().toISOString()}\n- Privacy note: no wallet secrets, credentials, or personal data included\n\n### Reproduction steps\n${steps}\n\n### Expected behavior\n${expected}\n\n### Actual behavior\n${actual}\n\n### Public evidence\n${evidence||'Not attached'}\n\n### Maintainer notes\n- Please verify against official Arc sources and the current supported wallet/network configuration.\n- This is a local draft generated by Arc Mainnet Desk; review it before sharing.`;document.querySelector('#brief-text').textContent=text;document.querySelector('#brief-result').hidden=false;document.querySelector('#brief-result').scrollIntoView({behavior:'smooth',block:'nearest'});});
