async function rpcCall(endpoint,method,params=[]){const response=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params})});if(!response.ok)throw new Error(`HTTP ${response.status}`);const body=await response.json();if(body.error)throw new Error(body.error.message||'RPC error');return body.result}
