function escapeHtml(value){return String(value).replace(/[&<>"']/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]))}
async function runDiagnostics(){const endpoint=rpcInput.value.trim();let parsed;try{parsed=new URL(endpoint);if(parsed.protocol!=='https:')throw new Error()}catch{monitorResults.innerHTML='<div class="rpc-error">Enter a valid HTTPS JSON-RPC endpoint.</div>';return}runMonitor.disabled=true;runMonitor.textContent='Running…';copyDiagnostics.disabled=true;monitorResults.innerHTML='<div class="empty-monitor"><span>⌁</span><p>Running read-only checks…<br /><small>No wallet connection is requested.</small></p></div>';const started=performance.now();try{const [chainId,blockNumber]=await Promise.all([rpcCall(endpoint,'eth_chainId'),rpcCall(endpoint,'eth_blockNumber')]);const latestBlock=await rpcCall(endpoint,'eth_getBlockByNumber',['latest',false]);const latency=Math.round(performance.now()-started);const timestamp=latestBlock?.timestamp?Number.parseInt(latestBlock.timestamp,16):null;const age=timestamp?Math.max(0,Math.round(Date.now()/1000-timestamp)):null;monitorResults.innerHTML=`<div class="result-grid"><div class="metric good"><small>CHAIN ID</small><b>${escapeHtml(chainId)}</b></div><div class="metric good"><small>LATEST BLOCK</small><b>${escapeHtml(formatHex(blockNumber))}</b></div><div class="metric ${age!==null&&age>120?'warn':'good'}"><small>BLOCK AGE</small><b>${age===null?'Unavailable':`${age}s`}</b></div><div class="metric good"><small>ROUND-TRIP</small><b>${latency} ms</b></div><div class="metric"><small>RPC HOST</small><b>${escapeHtml(parsed.host)}</b></div><div class="metric"><small>MODE</small><b>Read-only</b></div></div>`;latestDiagnostic=`ARC MAINNET DESK — RPC DIAGNOSTIC\n\nEndpoint host: ${parsed.host}\nChecked at: ${new Date().toISOString()}\nChain ID: ${chainId}\nLatest block: ${formatHex(blockNumber)}\nBlock age: ${age===null?'Unavailable':`${age}s`}\nRound-trip: ${latency} ms\n\nMethods: eth_chainId, eth_blockNumber, eth_getBlockByNumber\nMode: client-side, read-only\nNote: Verify endpoint ownership and results against official Arc sources.`;copyDiagnostics.disabled=false;refreshBundleStats?.();notify('Read-only diagnostic completed.')}catch(error){monitorResults.innerHTML=`<div class="rpc-error"><b>Diagnostic could not complete.</b><br />${escapeHtml(error.message||'The endpoint did not return a valid JSON-RPC response.')}<br /><br /><span>This can be caused by endpoint availability, browser CORS policy, or an invalid URL — it is not a chain-status conclusion.</span></div>`}finally{runMonitor.disabled=false;runMonitor.textContent='Run checks'}}
runMonitor.addEventListener('click',runDiagnostics);copyDiagnostics.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestDiagnostic);notify('Diagnostic report copied locally.')}catch{notify('Copy is unavailable in this browser.')}});
const walletSurfaces=[['MetaMask','Browser extension'],['Rabby','Browser extension'],['Coinbase Wallet','Browser extension'],['WalletConnect','Mobile / QR session']];
const matrixBody=document.querySelector('#matrix-body'),matrixSummary=document.querySelector('#matrix-summary'),testDialog=document.querySelector('#test-dialog'),testForm=document.querySelector('#test-form');let selectedWalletIndex=0;
