function renderMatrix(){const data=matrixData();let checks=0;matrixBody.innerHTML=walletSurfaces.map(([name,type],i)=>{const row=data[i]||{};const states=['connect','network','disconnect','approval'].map(area=>{if(row[area])checks++;return `<td>${stateChip(row[area])}</td>`}).join('');const dates=Object.values(row).map(v=>v?.date).filter(Boolean).sort().reverse();return `<tr><td class="wallet-name"><b>${name}</b><small>${type}</small></td>${states}<td class="last-tested">${escapeHtml(dates[0]||'—')}</td><td><button class="record-test" data-wallet="${i}">Record test <span>→</span></button></td></tr>`}).join('');matrixSummary.textContent=`${checks} check${checks===1?'':'s'} recorded · stored in this browser`;document.querySelectorAll('.record-test').forEach(button=>button.addEventListener('click',()=>openTestDialog(+button.dataset.wallet)))}
