document.querySelector('#export-matrix').addEventListener('click',async()=>{const data=matrixData();const rows=walletSurfaces.map(([name,type],i)=>{const row=data[i]||{};const value=area=>row[area]?`${{passed:'Passed',testing:'Needs testing',issue:'Known issue'}[row[area].status]}${row[area].note?` — ${row[area].note}`:''}`:'Needs testing';return `- ${name} (${type})\n  - Connect: ${value('connect')}\n  - Network switch: ${value('network')}\n  - Disconnect: ${value('disconnect')}\n  - Payment approval: ${value('approval')}`}).join('\n');const report=`## Arc Wallet Compatibility Matrix\n\nGenerated: ${new Date().toISOString()}\nScope: local, user-recorded test results only.\n\n${rows}\n\nNotes:\n- Untested states are not compatibility claims.\n- Review all results before sharing and exclude wallet addresses, secrets, or personal data.`;try{await navigator.clipboard.writeText(report);notify('Matrix report copied locally.')}catch{notify('Copy is unavailable in this browser.')}});
