const bundleReadiness=document.querySelector('#bundle-readiness'),bundleWallets=document.querySelector('#bundle-wallets'),bundleRpc=document.querySelector('#bundle-rpc'),bundleTx=document.querySelector('#bundle-tx'),bundleNotes=document.querySelector('#bundle-notes'),generateBundle=document.querySelector('#generate-bundle'),bundleResult=document.querySelector('#bundle-result'),bundleText=document.querySelector('#bundle-text'),copyBundle=document.querySelector('#copy-bundle');
