function shareablePaymentLink(intent){const url=new URL(window.location.href);url.search='';url.hash='reconciliation';url.searchParams.set('payTo',intent.recipient);url.searchParams.set('payAmount',usdcDisplay(intent.amount).replace(' USDC',''));if(intent.expiry)url.searchParams.set('payExpiry',intent.expiry);return url.href}
function loadSharedPaymentIntent(){const params=new URLSearchParams(window.location.search),recipient=params.get('payTo'),amount=params.get('payAmount');if(!recipient||!amount)return;reconcileRecipient.value=recipient;reconcileReference.value='';reconcileAmount.value=amount;const expiry=params.get('payExpiry');if(expiry){const parsed=new Date(expiry);if(!Number.isNaN(parsed.getTime()))reconcileExpiry.value=parsed.toISOString().slice(0,16)}createReconcileIntent();copyShareRequest.disabled=!localPaymentIntent}
