runBatch.addEventListener('click',runBatchReconciliation);copyBatch.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestBatchEvidence);notify('Batch evidence copied locally.')}catch{notify('Copy is unavailable in this browser.')}});downloadBatch.addEventListener('click',downloadBatchCsv);
const incidentRpcA=document.querySelector('#incident-rpc-a'),incidentRpcB=document.querySelector('#incident-rpc-b'),incidentMethod=document.querySelector('#incident-method'),incidentParams=document.querySelector('#incident-params'),runIncident=document.querySelector('#run-incident'),incidentResults=document.querySelector('#incident-results'),copyIncident=document.querySelector('#copy-incident');let latestIncidentReport='';
const safeIncidentMethods=new Set(['eth_chainId','eth_blockNumber','eth_getBlockByNumber','eth_getTransactionByHash','eth_getTransactionReceipt','eth_getCode','eth_getBalance','eth_call','net_version','web3_clientVersion']);
const sensitiveKeys=/authorization|api[-_]?key|token|secret|password|passwd|private[-_]?key|mnemonic|seed|credential|cookie/i;
function publicRpcHost(value){const parsed=new URL(value);if(parsed.protocol!=='https:')throw new Error('Endpoints must use HTTPS.');return parsed.host}
