async function incidentRpcCall(endpoint,method,params){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000),started=performance.now();try{const response=await fetch(endpoint,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:controller.signal});const latency=Math.round(performance.now()-started),text=await response.text();if(text.length>1000000)throw new Error('Response exceeded the 1 MB safety limit.');let body;try{body=JSON.parse(text)}catch{throw new Error(`HTTP ${response.status}; response was not valid JSON`)}if(!response.ok)throw new Error(`HTTP ${response.status}: ${body?.error?.message||'request failed'}`);if(body.error)return{ok:false,latency,error:{code:body.error.code,message:String(body.error.message||'RPC error')}};return{ok:true,latency,result:body.result}}catch(error){return{ok:false,latency:Math.round(performance.now()-started),error:{message:error.name==='AbortError'?'Request timed out after 10 seconds':String(error.message||'Request failed')}}}finally{clearTimeout(timer)}}
