async function reproduceIncident(){const endpointA=incidentRpcA.value.trim(),endpointB=incidentRpcB.value.trim(),method=incidentMethod.value;let params,hostA,hostB='Not supplied';if(!safeIncidentMethods.has(method)){incidentError('This method is not on the read-only allowlist.');return}try{hostA=publicRpcHost(endpointA);if(endpointB)hostB=publicRpcHost(endpointB)}catch(error){incidentError(error.message||'Enter a valid HTTPS RPC endpoint.');return}try{params=JSON.parse(incidentParams.value||'[]');if(!Array.isArray(params))throw new Error()}catch{incidentError('Parameters must be a valid JSON array. Example: ["latest", false]');return}runIncident.disabled=true;runIncident.textContent='Reproducing…';copyIncident.disabled=true;latestIncidentReport='';incidentResults.innerHTML='<div class="empty-incident"><span>⌘</span><p>Running bounded read-only request…<br />Sensitive fields will be redacted locally.</p></div>';try{const endpoints=[{label:'A',url:endpointA,host:hostA},...(endpointB?[{label:'B',url:endpointB,host:hostB}]:[])],observations=await Promise.all(endpoints.map(async endpoint=>({...endpoint,...await incidentRpcCall(endpoint.url,method,params)}))),safeParams=redactIncidentValue(params),safeObservations=observations.map(({label,host,ok,latency,result,error})=>({label,host,ok,latency_ms:latency,response:redactIncidentValue(ok?result:error)})),normalized=safeObservations.map(item=>JSON.stringify(stableIncidentValue({ok:item.ok,response:item.response}))),agreement=safeObservations.length===1?'Single endpoint':normalized[0]===normalized[1]?'Responses agree':'Responses differ';incidentResults.innerHTML=`<div class="incident-status"><b>OBSERVED RPC REPRODUCTION</b><span class="${agreement==='Responses differ'?'different':''}">${escapeHtml(agreement)}</span></div><div class="incident-cards">${safeObservations.map(item=>`<div class="incident-card"><small>ENDPOINT ${item.label} · ${escapeHtml(item.host)}</small><b>${item.ok?'Response returned':'Error returned'} · ${item.latency_ms} ms</b><code>${escapeHtml(JSON.stringify(item.response,null,2).slice(0,6000))}</code></div>`).join('')}</div><p class="incident-note">Credentials and query strings are excluded from this view. Review the report before sharing; automated redaction cannot guarantee complete privacy.</p>`;latestIncidentReport=`# Arc Mainnet Desk — Redacted RPC Incident Report\n\nGenerated: ${new Date().toISOString()}\nMethod: ${method}\nParameters: \`${JSON.stringify(safeParams)}\`\nComparison: ${agreement}\nMode: client-side, read-only, 10-second timeout per endpoint\n\n## Observations\n${safeObservations.map(item=>`\n### Endpoint ${item.label}\n- Host: ${item.host}\n- Result: ${item.ok?'response returned':'error returned'}\n- Browser round-trip: ${item.latency_ms} ms\n\n\`\`\`json\n${JSON.stringify(item.response,null,2).slice(0,12000)}\n\`\`\``).join('\n')}\n\n## Reproduction steps\n1. Use a trusted HTTPS Arc RPC endpoint.\n2. Call \`${method}\` with the redacted parameters above.\n3. Compare the returned JSON with the recorded observation.\n\n## Privacy and claim boundary\n- Endpoint credentials and query strings were not retained; sensitive-looking fields were redacted locally.\n- Automated redaction is not a guarantee. Review this report before sharing.\n- Results are browser observations from supplied endpoints, not proof of endpoint ownership, network health, or an official Arc conclusion.\n- No wallet connection, signature, or write method was requested.`;copyIncident.disabled=false;notify(`RPC incident reproduced: ${agreement}.`)}catch(error){incidentError(error.message||'The incident reproduction could not complete.')}finally{runIncident.disabled=false;runIncident.innerHTML='Run safe reproduction <span>→</span>'}}
runIncident.addEventListener('click',reproduceIncident);copyIncident.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestIncidentReport);notify('Redacted incident report copied locally.')}catch{notify('Copy is unavailable in this browser.')}});
