const assessGate=document.querySelector('#assess-gate'),gateResult=document.querySelector('#gate-result'),copyGate=document.querySelector('#copy-gate');let latestGateReport='';
function gateRequirements(){return[{label:'Readiness checklist',detail:`${readinessData().length} / ${readiness.length} tasks complete`,met:readinessData().length===readiness.length},{label:'Wallet journey evidence',detail:`${countWalletChecks()} recorded check${countWalletChecks()===1?'':'s'}`,met:countWalletChecks()>0},{label:'RPC diagnostic',detail:latestDiagnostic?'Recorded this session':'Not recorded this session',met:Boolean(latestDiagnostic)},{label:'Network configuration',detail:latestNetworkReport?'Recorded this session':'Not recorded this session',met:Boolean(latestNetworkReport)},{label:'RPC consistency',detail:latestConsistencyReport?'Recorded this session':'Not recorded this session',met:Boolean(latestConsistencyReport)},{label:'Cross-RPC receipt witness',detail:latestWitnessReport?'Recorded this session':'Not recorded this session',met:Boolean(latestWitnessReport)},{label:'Transaction evidence',detail:latestEvidence?'Recorded this session':'Not recorded this session',met:Boolean(latestEvidence)},{label:'Payment reliability observation',detail:latestPaymentReport?'Recorded this session':'Not recorded this session',met:Boolean(latestPaymentReport)},{label:'Payment intent verification',detail:latestIntentReport?'Recorded this session':'Not recorded this session',met:Boolean(latestIntentReport)},{label:'Redacted RPC incident reproduction',detail:latestIncidentReport?'Recorded this session':'Not recorded this session',met:Boolean(latestIncidentReport)}]}
function assessReleaseGate(){const checks=gateRequirements(),completed=checks.filter(check=>check.met).length,status=completed===checks.length?'Evidence complete':completed>=4?'Needs review':'Not ready',statusClass=status.toLowerCase().replaceAll(' ','-'),missing=checks.filter(check=>!check.met).map(check=>check.label);gateResult.innerHTML=`<div class="gate-status"><b>LOCAL REVIEW RESULT</b><span class="gate-badge ${statusClass}">${status}</span></div><div class="gate-checks">${checks.map(check=>`<div class="gate-check ${check.met?'ok':'missing'}"><b>${check.met?'✓ RECORDED':'○ MISSING'}</b>${escapeHtml(check.label)}<br /><span>${escapeHtml(check.detail)}</span></div>`).join('')}</div><p class="gate-note">${status==='Evidence complete'?'All items in this local standard are recorded. Independently review the evidence before any promotion.':`Missing evidence: ${escapeHtml(missing.join(', '))}.`}</p>`;latestGateReport=`# Arc Mainnet Desk — Local Release Gate\n\nAssessed: ${new Date().toISOString()}\nResult: ${status}\nCompleted local standard: ${completed} / ${checks.length}\n\n## Evidence standard\n${checks.map(check=>`- [${check.met?'x':' '}] ${check.label} — ${check.detail}`).join('\n')}\n\n## Missing evidence\n${missing.length?missing.map(item=>`- ${item}`).join('\n'):'- None in this local standard.'}\n\n## Review boundary\n- This is a local reviewer aid based only on evidence recorded in this browser session.\n- It is not a security audit, network-health signal, official Arc approval, or release authorization.\n- Review every underlying report and verify official configuration before making a launch claim.`;copyGate.disabled=false;notify(`Local release gate: ${status}.`)}
assessGate.addEventListener('click',assessReleaseGate);copyGate.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestGateReport);notify('Release-gate report copied locally.')}catch{notify('Copy is unavailable in this browser.')}});

/* A focused workspace replaces an endlessly long landing page. */
const workflowBanner=document.getElementById('workflow-banner');
const workflowKicker=document.getElementById('workflow-kicker');
const workflowTitle=document.getElementById('workflow-title');
const workflowNames={overview:['OVERVIEW','Choose a workflow'],payments:['PAYMENTS','Payment verification & reconciliation'],quality:['QA & RELIABILITY','Diagnostics & reproducible evidence'],release:['RELEASE READINESS','Evidence packs & local release gate']};
const workflowHashMap={'workspace':'quality','monitor':'quality','payment-lab':'payments','intent-lab':'payments','swap-inspector':'payments','reconciliation':'payments','incident-lab':'quality','agentic-brief':'quality','evidence':'quality','network':'quality','consistency':'quality','receipt-witness':'quality','resolver':'quality','matrix':'quality','report':'quality','contract-watch':'quality','changelog':'release','bundle':'release','release-pack':'release','release-gate':'release','checklist':'release','safety':'release','scorecard':'release'};
function setWorkspaceMode(mode){
  const safeMode=workflowNames[mode]?mode:'overview';
  document.body.dataset.workspaceMode=safeMode;
  if(workflowBanner){workflowBanner.hidden=safeMode==='overview';workflowKicker.textContent=workflowNames[safeMode][0];workflowTitle.textContent=workflowNames[safeMode][1];}
}
function syncWorkspaceMode(){
  const hash=window.location.hash.slice(1);
  setWorkspaceMode(workflowHashMap[hash]||'overview');
}
document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',()=>{
  const hash=link.getAttribute('href').slice(1);
  setWorkspaceMode(workflowHashMap[hash]||'overview');
}));
window.addEventListener('hashchange',syncWorkspaceMode);
syncWorkspaceMode();

// Merchant Checkout Handoff: generate a plain HTML link from the existing local
// payment request. No QR service, analytics endpoint, wallet request, or remote
// persistence is involved.
const checkoutKit=document.querySelector('#checkout-kit'),checkoutStatus=document.querySelector('#checkout-request-status'),generateCheckoutEmbed=document.querySelector('#generate-checkout-embed'),copyCheckoutEmbed=document.querySelector('#copy-checkout-embed'),checkoutCode=document.querySelector('#checkout-code');let latestCheckoutEmbed='';
function checkoutRequestState(intent){
  if(!intent)return{label:'AWAITING REQUEST',expired:false};
  const expired=Boolean(intent.expiry&&new Date(intent.expiry).getTime()<=Date.now());
  return{label:expired?'EXPIRED · REVIEW':'VALIDATED LOCAL PARAMETERS',expired};
}
function refreshCheckoutKit(){
  if(!checkoutKit)return;
  const state=checkoutRequestState(localPaymentIntent);
  checkoutKit.hidden=!localPaymentIntent;
  checkoutStatus.textContent=state.label;
  checkoutStatus.classList.toggle('expired',state.expired);
  generateCheckoutEmbed.disabled=!localPaymentIntent||state.expired;
  if(!localPaymentIntent){copyCheckoutEmbed.disabled=true;checkoutCode.textContent='Create a local request to generate a checkout snippet.';}
}
function buildCheckoutEmbed(){
  if(!localPaymentIntent)return;
  const state=checkoutRequestState(localPaymentIntent);
  if(state.expired){notify('This local payment request has expired. Create a new request before sharing it.');return;}
  const url=shareablePaymentLink(localPaymentIntent);
  latestCheckoutEmbed=`<!-- Arc Mainnet Desk: read-only payment request -->\n<a href="${escapeHtml(url)}" rel="noopener noreferrer">\n  Pay ${escapeHtml(usdcDisplay(localPaymentIntent.amount))} on Arc Mainnet\n</a>\n<!-- Opens a payment request only. Wallet connection and transaction submission are not performed here. -->`;
  checkoutCode.textContent=latestCheckoutEmbed;
  copyCheckoutEmbed.disabled=false;
  notify('Checkout link snippet generated locally.');
}
generateCheckoutEmbed?.addEventListener('click',buildCheckoutEmbed);
copyCheckoutEmbed?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestCheckoutEmbed);notify('Checkout embed code copied locally.')}catch{notify('Copy is unavailable in this browser.')}});
saveReconcileIntent?.addEventListener('click',()=>setTimeout(refreshCheckoutKit,0));
refreshCheckoutKit();

// Merchant receipt export: browser-local only. It packages the existing local request
// with the already-rendered public receipt observation; it never calls a wallet API.
const downloadReceipt=document.querySelector('#download-receipt');
function merchantReceiptPayload(){
  return {
    schema:'arc-mainnet-desk/merchant-receipt/v1',
    generated_at:new Date().toISOString(),
    mode:'client-side, read-only',
    local_payment_request:localPaymentIntent?{
      recipient:localPaymentIntent.recipient,
      requested_amount:usdcDisplay(localPaymentIntent.amount),
      merchant_reference:localPaymentIntent.reference||null,
      expiry:localPaymentIntent.expiry||null,
      created_at:localPaymentIntent.createdAt
    }:null,
    public_receipt:{
      transaction_hash:reconcileHash.value.trim()||null,
      rpc_host:(()=>{try{return new URL(reconcileRpc.value.trim()).host}catch{return null}})(),
      observed_result:reconciliationResults.innerText.replace(/\s+/g,' ').trim()||null
    },
    review_boundary:'This local export is a review aid, not an invoice, settlement confirmation, accounting record, security audit, or official Arc record. Review the public transaction independently.'
  };
}
function refreshMerchantReceiptExport(){
  if(!downloadReceipt)return;
  downloadReceipt.disabled=!localPaymentIntent||copyReconciliation.disabled;
}
downloadReceipt?.addEventListener('click',()=>{
  const data=merchantReceiptPayload();
  const blob=new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json;charset=utf-8'});
  const anchor=document.createElement('a');
  anchor.href=URL.createObjectURL(blob);
  anchor.download=`arc-merchant-receipt-${new Date().toISOString().slice(0,10)}.json`;
  anchor.click();
  URL.revokeObjectURL(anchor.href);
  notify('Merchant receipt downloaded locally.');
});
runReconciliation?.addEventListener('click',()=>setTimeout(refreshMerchantReceiptExport,0));
document.querySelector('#save-reconcile-intent')?.addEventListener('click',()=>setTimeout(refreshMerchantReceiptExport,0));
if(copyReconciliation&&window.MutationObserver){new MutationObserver(refreshMerchantReceiptExport).observe(copyReconciliation,{attributes:true,attributeFilter:['disabled']});}
refreshMerchantReceiptExport();

// ArcHandle preview deliberately has no wallet, X, backend, or network integration.
// It exists to make the future payment boundary inspectable before real funds are enabled.
const arcHandleForm=document.querySelector('#arc-handle-form');
const arcHandleRecipient=document.querySelector('#arc-handle-recipient');
const arcHandleAmount=document.querySelector('#arc-handle-amount');
const arcHandleResult=document.querySelector('#arc-handle-result');
function arcHandlePreviewError(message){if(arcHandleResult)arcHandleResult.innerHTML=`<div class="arc-handle-preview"><div class="arc-handle-preview-head"><b>ROUTE NOT READY</b><span class="arc-handle-badge">LOCAL CHECK</span></div><p class="arc-handle-note">${escapeHtml(message)} No X account, wallet, or network request was made.</p></div>`}
arcHandleForm?.addEventListener('submit',event=>{event.preventDefault();const raw=arcHandleRecipient.value.trim().replace(/^@+/,'');const amount=arcHandleAmount.value.trim();if(!/^[A-Za-z0-9_]{1,15}$/.test(raw)){arcHandlePreviewError('Enter a valid X-style handle using 1–15 letters, numbers, or underscores.');return}if(amount&&(!/^\d+(?:\.\d{1,18})?$/.test(amount)||Number(amount)<=0)){arcHandlePreviewError('Enter a positive USDC amount with up to 18 decimal places, or leave it blank for a route-only review.');return}const displayAmount=amount?`${amount} USDC`:'Amount to be confirmed';arcHandleResult.innerHTML=`<div class="arc-handle-preview"><div class="arc-handle-preview-head"><b>PROPOSED PAYMENT ROUTE</b><span class="arc-handle-badge">NOT ENABLED</span></div><div class="arc-handle-route"><b>Sender wallet</b><span>→</span><b>@${escapeHtml(raw)}</b></div><div class="arc-handle-route"><b>${escapeHtml(displayAmount)}</b><span>·</span><b>Arc Mainnet</b></div><p class="arc-handle-note">Before any transfer is possible, <b>@${escapeHtml(raw)}</b> must authenticate through X OAuth and claim a wallet. The production flow will show the recipient identity and require the sender’s explicit approval.</p></div>`;notify('Payment route previewed locally; transfers remain disabled.');});

// Agentic Operations Brief: a local design aid, deliberately not an agent runtime.
const agenticForm=document.querySelector('#agentic-form');
const agenticGoal=document.querySelector('#agentic-goal');
const agenticOutput=document.querySelector('#agentic-output');
const copyAgenticBrief=document.querySelector('#copy-agentic-brief');
let latestAgenticBrief='';
agenticForm?.addEventListener('submit',event=>{
  event.preventDefault();
  const evidence=[
    document.querySelector('#agentic-receipts')?.checked?'public transaction receipts':null,
    document.querySelector('#agentic-intents')?.checked?'browser-local payment requests':null,
    document.querySelector('#agentic-rpc')?.checked?'read-only RPC diagnostics':null
  ].filter(Boolean);
  const goal=agenticGoal.value.trim()||'Triage payment-operation exceptions';
  const humanReview=document.querySelector('#agentic-review')?.checked;
  const noWallet=document.querySelector('#agentic-no-wallet')?.checked;
  const guardrails=[humanReview?'Every proposed next action requires human approval.':'Human approval boundary is missing — add it before implementation.',noWallet?'The workflow has no wallet access or signing authority.':'Wallet/signing access must remain disabled.'];
  latestAgenticBrief=`# Arc Mainnet Desk — Agentic Operations Brief\n\nGoal: ${goal}\n\n## Read scope\n${evidence.length?evidence.map(item=>`- ${item}`).join('\n'):'- No evidence sources selected.'}\n\n## Bounded workflow\n1. Read only the permitted evidence sources.\n2. Group observations into matched, incomplete, or review-required cases.\n3. Produce a concise queue with links or identifiers supplied by the operator.\n4. Propose next steps; do not execute them.\n\n## Required guardrails\n${guardrails.map(item=>`- ${item}`).join('\n')}\n- No custody, transfers, signing, autonomous payment decisions, or private-key handling.\n- Treat output as an operational suggestion, not an accounting conclusion or network attestation.\n\nMode: local design canvas only. No AI model, remote service, wallet, or transaction was invoked.`;
  agenticOutput.innerHTML=`<pre>${escapeHtml(latestAgenticBrief)}</pre>`;
  copyAgenticBrief.disabled=false;
  notify('Agentic workflow brief generated locally.');
});
copyAgenticBrief?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(latestAgenticBrief);notify('Agentic workflow brief copied locally.')}catch{notify('Copy is unavailable in this browser.')}});
